import pickle,numpy as np
from collections import Counter
from rdkit import Chem
ms,offs,els,adj=pickle.load(open('metadata.pkl','rb'));p=np.load('best.npy')
print(Counter(els),offs)
for m,off in zip(ms,offs):
 print(off,Chem.MolToSmiles(Chem.RemoveHs(m)))
 for a in m.GetAtoms():
  if a.GetSymbol() in ('Si','N','P','S','O'):print(off+a.GetIdx(),a.GetSymbol(),np.round(p[off+a.GetIdx()],2))
print('Metal positions:',p[:3]);
for i in [offs[0],offs[1],offs[2]]: print('Rh donor',els[i],np.linalg.norm(p[i]-p[0]))
cl=[]
for i in range(len(p)):
 ex=set(adj[i]);ex.add(i)
 for j in adj[i]:ex|=adj[j]
 for j in range(i+1,len(p)):
  if j in ex:continue
  r=np.linalg.norm(p[i]-p[j])
  if r<1.5:cl.append((i,j,els[i],els[j],r))
print('nonbonded below1.5',cl)
